//! Setting presentation metadata and the settings-screen schema.
//!
//! [`SettingMeta`] is generated from the `#[setting(..)]` attributes on
//! `AppSettings` by `#[derive(SettingsMeta)]`; this module only assembles the
//! generated metadata into tabs/sections for `get_settings_schema`.

use serde::Serialize;
use serde_json::Value;

use super::AppSettings;

/// One setting's presentation metadata, generated by `#[derive(SettingsMeta)]`.
///
/// Serialized into the `get_settings_schema` payload. `section` is not serialized:
/// it only routes the setting into the right tab/section during assembly.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SettingMeta {
    pub id: String,
    pub label: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    pub keywords: Vec<String>,
    #[serde(rename = "type")]
    pub kind: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub options: Option<Vec<SettingOption>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub min: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_value: Option<Value>,
    #[serde(skip)]
    pub section: &'static str,
}

/// A select option; `value` is JSON so it can be a string or a number.
#[derive(Debug, Clone, Serialize)]
pub struct SettingOption {
    pub value: Value,
    pub label: String,
}

/// A tab/section in the settings screen. `key` is what `#[setting(section = ..)]`
/// references; tabs are grouped in first-appearance order.
struct SectionDef {
    key: &'static str,
    tab: &'static str,
    tab_label: &'static str,
    name: &'static str,
}

const SETTING_SECTIONS: &[SectionDef] = &[
    SectionDef {
        key: "plan_calendar",
        tab: "plan_screen",
        tab_label: "Plan screen",
        name: "Calendar",
    },
    SectionDef {
        key: "do_stopwatch",
        tab: "do_screen",
        tab_label: "Do screen",
        name: "Stopwatch",
    },
    SectionDef {
        key: "keybindings",
        tab: "keybindings",
        tab_label: "Keybindings",
        name: "Keybindings",
    },
    SectionDef {
        key: "tracker_appearance",
        tab: "tracker_window",
        tab_label: "Tracker window",
        name: "Appearance",
    },
];

#[derive(Serialize)]
struct SchemaSection {
    name: &'static str,
    settings: Vec<SettingMeta>,
}

#[derive(Serialize)]
struct SchemaTab {
    id: &'static str,
    label: &'static str,
    sections: Vec<SchemaSection>,
}

#[derive(Serialize)]
struct SchemaRoot {
    tabs: Vec<SchemaTab>,
}

fn build_settings_schema() -> SchemaRoot {
    let mut tabs: Vec<SchemaTab> = Vec::new();
    let metadata = AppSettings::setting_metadata();

    for def in SETTING_SECTIONS {
        let settings: Vec<SettingMeta> = metadata
            .iter()
            .filter(|meta| meta.section == def.key)
            .cloned()
            .collect();

        let section = SchemaSection {
            name: def.name,
            settings,
        };

        if let Some(tab) = tabs.iter_mut().find(|tab| tab.id == def.tab) {
            tab.sections.push(section);
        } else {
            tabs.push(SchemaTab {
                id: def.tab,
                label: def.tab_label,
                sections: vec![section],
            });
        }
    }

    SchemaRoot { tabs }
}

/// Serialize the schema to JSON.
///
/// `serde_json`'s default map is a `BTreeMap`, so key order is deterministic.
/// Tests assert the wire contract structurally rather than pinning a full golden
/// blob, which would be a change-detector; the user-visible label/keyword/option
/// strings are pinned separately in `tests.rs`.
pub(super) fn settings_schema_value() -> Value {
    // `SchemaRoot` is plain data, so serialization is infallible.
    serde_json::to_value(build_settings_schema()).unwrap_or(Value::Null)
}

#[cfg(test)]
mod tests;
